mapper.select:


    p.del_flag = '0'

        and p.paper_name like concat('%', #{paperName}, '%')


        and p.creator_id = #{creatorId}


        and (p.course_id = #{courseId}
             or exists (select 1 from edu_paper_course pc where pc.paper_id = p.paper_id and pc.course_id = #{courseId}))


        and p.bank_id = #{bankId}


        and p.status = #{status}


order by p.paper_id desc

mapper.insert:
insert into edu_paper (
    paper_name, creator_id, course_id, bank_id, paper_desc, total_score, question_count,
    objective_score, subjective_score, compose_mode, status, del_flag, create_by, create_time, remark
) values (
    #{paperName}, #{creatorId}, #{courseId}, #{bankId}, #{paperDesc}, #{totalScore}, #{questionCount},
    #{objectiveScore}, #{subjectiveScore}, #{composeMode}, #{status}, '0', #{createBy}, sysdate(), #{remark}
)

mapper.update:
update edu_paper
paper_name = #{paperName}, course_id = #{courseId}, bank_id = #{bankId}, paper_desc = #{paperDesc}, total_score = #{totalScore}, question_count = #{questionCount}, objective_score = #{objectiveScore}, subjective_score = #{subjectiveScore}, compose_mode = #{composeMode}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where paper_id = #{paperId}

update edu_paper p
set p.question_count = (
        select count(1) from edu_paper_question pq where pq.paper_id = #{paperId}
    ),
    p.total_score = (
        select coalesce(sum(pq.question_score), 0) from edu_paper_question pq where pq.paper_id = #{paperId}
    ),
    p.objective_score = (
        select coalesce(sum(pq.question_score), 0) from edu_paper_question pq
        where pq.paper_id = #{paperId} and pq.question_type in ('1', '2', '3', '4')
    ),
    p.subjective_score = (
        select coalesce(sum(pq.question_score), 0) from edu_paper_question pq
        where pq.paper_id = #{paperId} and pq.question_type = '5'
    ),
    p.update_time = sysdate()
where p.paper_id = #{paperId}
